/**
 * Shared ranking-metric primitives + per-benchmark wrappers (BrainBench v0.5.0).
 *
 * One denominator policy, one place to test. This file replaces the ~7
 * divergent recall/precision implementations that previously lived in
 * cat6 / cat15 / cat18 / cat18b / cat21 / cat26 / multi-adapter /
 * shootout-driver (audit 2026-08-31, findings shared-infra-02/03 and
 * the critic's cross-cut).
 *
 * Contract (WS0):
 *   - Callers pass NORMALIZED id lists. Chunk→page and turn→session mapping
 *     is the runner's explicit job — a chunk-grained result list handed to
 *     recallAtK will double-count and that is the caller's bug, not this
 *     file's leniency. Normalize first (`uniqueInOrder` helps).
 *   - Gold sets are Sets, so duplicates in gold cannot inflate denominators.
 *   - Binary recall_all (LongMemEval-style), fractional recall, and graded
 *     nDCG are DIFFERENT metrics with different formulas. They are separate
 *     functions here, not flags on one function.
 */

// ─── Primitives ──────────────────────────────────────────────────────

/** First occurrence of each id, order preserved. Use to normalize chunk-grained results. */
export function uniqueInOrder(ids: readonly string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const id of ids) {
    if (!seen.has(id)) {
      seen.add(id);
      out.push(id);
    }
  }
  return out;
}

/** Count of DISTINCT relevant ids present in the list (duplicates count once). */
export function uniqueHits(ids: readonly string[], relevant: ReadonlySet<string>): number {
  const matched = new Set<string>();
  for (const id of ids) if (relevant.has(id)) matched.add(id);
  return matched.size;
}

/** 1-based rank of the first relevant id; Infinity when none is present. */
export function rankOfFirstHit(ids: readonly string[], relevant: ReadonlySet<string>): number {
  for (let i = 0; i < ids.length; i++) {
    if (relevant.has(ids[i])) return i + 1;
  }
  return Infinity;
}

/**
 * Percentile with linear interpolation on the sorted copy (inclusive method,
 * same as numpy.percentile default). p in [0, 100]. Returns NaN on empty input
 * so callers cannot mistake "no data" for "0ms".
 */
export function percentile(values: readonly number[], p: number): number {
  if (values.length === 0) return NaN;
  const sorted = [...values].sort((a, b) => a - b);
  const idx = (Math.min(Math.max(p, 0), 100) / 100) * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

// ─── Fractional recall / precision (BrainBench relational metrics) ──

/**
 * Recall@k: fraction of the relevant set found in the top-k, counting each
 * relevant id at most once. Never exceeds 1.0. Empty relevant set returns NaN
 * — exclude such queries from means instead of averaging in a fake 0.
 */
export function recallAtK(ids: readonly string[], relevant: ReadonlySet<string>, k: number): number {
  if (relevant.size === 0) return NaN;
  return uniqueHits(ids.slice(0, k), relevant) / relevant.size;
}

/**
 * Precision@k with the standard /k denominator. An adapter that returns fewer
 * than k results is scored as if the missing slots were misses — returning
 * one relevant doc is NOT P@10 = 1.0 (audit finding shared-infra-03).
 */
export function precisionAtK(ids: readonly string[], relevant: ReadonlySet<string>, k: number): number {
  if (k <= 0) return NaN;
  return uniqueHits(ids.slice(0, k), relevant) / k;
}

/** Mean Reciprocal Rank contribution for one query: 1/rank of first hit, 0 if no hit. */
export function reciprocalRank(ids: readonly string[], relevant: ReadonlySet<string>): number {
  const r = rankOfFirstHit(ids, relevant);
  return Number.isFinite(r) ? 1 / r : 0;
}

// ─── Binary recall_all (LongMemEval official definition) ────────────

/**
 * recall_all@k: 1 if EVERY relevant id appears in the top-k, else 0. This is
 * the official LongMemEval session-level metric (`all(doc in recalled_docs
 * for doc in correct_docs)`), the number published systems report against.
 * Any-hit recall is a strictly looser metric — never present it as this one.
 */
export function recallAllAtK(ids: readonly string[], relevant: ReadonlySet<string>, k: number): number {
  if (relevant.size === 0) return NaN;
  const top = new Set(ids.slice(0, k));
  for (const r of relevant) if (!top.has(r)) return 0;
  return 1;
}

/** Any-hit recall@k: 1 if at least one relevant id is in the top-k. Diagnostic only. */
export function recallAnyAtK(ids: readonly string[], relevant: ReadonlySet<string>, k: number): number {
  if (relevant.size === 0) return NaN;
  return uniqueHits(ids.slice(0, k), relevant) > 0 ? 1 : 0;
}

// ─── Graded nDCG ─────────────────────────────────────────────────────

/**
 * DCG@k over graded relevance. `grades` maps id → gain (missing id = 0).
 * Uses the standard log2 discount: sum(grade_i / log2(i + 1)), 1-based i.
 */
export function dcgAtK(ids: readonly string[], grades: ReadonlyMap<string, number>, k: number): number {
  let dcg = 0;
  const top = ids.slice(0, k);
  for (let i = 0; i < top.length; i++) {
    const g = grades.get(top[i]) ?? 0;
    if (g !== 0) dcg += g / Math.log2(i + 2);
  }
  return dcg;
}

/** nDCG@k: DCG normalized by the ideal ordering of the graded set. NaN when no positive grades. */
export function ndcgAtK(ids: readonly string[], grades: ReadonlyMap<string, number>, k: number): number {
  const ideal = [...grades.entries()]
    .filter(([, g]) => g > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => id);
  if (ideal.length === 0) return NaN;
  const idcg = dcgAtK(ideal, grades, k);
  if (idcg === 0) return NaN;
  return dcgAtK(ids, grades, k) / idcg;
}

eval/runner/queries/relational.ts.source_utf8:
/**
 * Shared world-v1 relational query builder + corpus loader.
 *
 * ONE implementation of the "derive relational gold from _facts" logic.
 * Both eval/runner/multi-adapter.ts and eval/runner/shootout-driver.ts
 * previously carried private copies, and the shootout copy silently dropped
 * the invested_in and advises templates while its receipt reused the same
 * mean_precision_at_k / mean_recall_at_k field names as the multi-adapter
 * scorecard (audit finding orchestrators-15). Sharing the builder makes the
 * two runners' relational numbers comparable by construction.
 *
 * Four templates, all tier 'medium', gold from the page's _facts metadata:
 *   - "Who attended <meeting title>?"     gold = attendees
 *   - "Who works at <company title>?"     gold = employees + founders
 *   - "Who invested in <company title>?"  gold = investors
 *   - "Who advises <company title>?"      gold = advisors
 */

import { readdirSync, readFileSync } from 'fs';
import { join } from 'path';
import type { Page, Query } from '../types.ts';

/** world-v1 page shape including the gold-canonical _facts metadata.
 *  _facts is scorer-only: multi-adapter/shootout-driver sanitizePage()
 *  before anything reaches an adapter. */
export interface RichPage extends Page {
  _facts: {
    type: string;
    role?: string;
    primary_affiliation?: string;
    secondary_affiliations?: string[];
    founders?: string[];
    employees?: string[];
    investors?: string[];
    advisors?: string[];
    attendees?: string[];
  };
}

/**
 * Load the world-v1 corpus from a directory of per-page JSON shards.
 * Filenames are sorted so page order (and therefore the generated q-NNNN
 * ids and the seeded per-run shuffles downstream) is identical on every
 * filesystem, not dependent on readdir order.
 */
export function loadWorldCorpus(dir: string): RichPage[] {
  const files = readdirSync(dir)
    .filter(f => f.endsWith('.json') && !f.startsWith('_'))
    .sort();
  const out: RichPage[] = [];
  for (const f of files) {
    const p = JSON.parse(readFileSync(join(dir, f), 'utf-8'));
    if (Array.isArray(p.timeline)) p.timeline = p.timeline.join('\n');
    if (Array.isArray(p.compiled_truth)) p.compiled_truth = p.compiled_truth.join('\n\n');
    p.title = String(p.title ?? '');
    p.compiled_truth = String(p.compiled_truth ?? '');
    p.timeline = String(p.timeline ?? '');
    out.push(p as RichPage);
  }
  return out;
}

/** Relational queries with gold derived from _facts. All 4 template families. */
export function buildRelationalQueries(pages: RichPage[]): Query[] {
  const existing = new Set(pages.map(p => p.slug));
  const filter = (slugs: string[]) => slugs.filter(s => existing.has(s));
  const queries: Query[] = [];
  let counter = 0;
  const nextId = () => `q-${String(++counter).padStart(4, '0')}`;

  // "Who attended X?" (meeting → people). Medium tier.
  for (const p of pages) {
    if (p._facts.type !== 'meeting') continue;
    const expected = filter(p._facts.attendees ?? []);
    if (expected.length === 0) continue;
    queries.push({
      id: nextId(),
      tier: 'medium',
      text: `Who attended ${p.title}?`,
      expected_output_type: 'cited-source-pages',
      gold: { relevant: expected },
    });
  }

  // "Who works at X?" (company → people). Medium.
  for (const p of pages) {
    if (p._facts.type !== 'company') continue;
    const expected = filter([...(p._facts.employees ?? []), ...(p._facts.founders ?? [])]);
    if (expected.length === 0) continue;
    queries.push({
      id: nextId(),
      tier: 'medium',
      text: `Who works at ${p.title}?`,
      expected_output_type: 'cited-source-pages',
      gold: { relevant: [...new Set(expected)] },
    });
  }

  // "Who invested in X?" Medium.
  for (const p of pages) {
    if (p._facts.type !== 'company') continue;
    const expected = filter(p._facts.investors ?? []);
    if (expected.length === 0) continue;
    queries.push({
      id: nextId(),
      tier: 'medium',
      text: `Who invested in ${p.title}?`,
      expected_output_type: 'cited-source-pages',
      gold: { relevant: expected },
    });
  }

  // "Who advises X?" Medium.
  for (const p of pages) {
    if (p._facts.type !== 'company') continue;
    const expected = filter(p._facts.advisors ?? []);
    if (expected.length === 0) continue;
    queries.push({
      id: nextId(),
      tier: 'medium',
      text: `Who advises ${p.title}?`,
      expected_output_type: 'cited-source-pages',
      gold: { relevant: expected },
    });
  }

  return queries;
}

eval/precisionmembench/seed.ts.source_utf8:
/**
 * seed.ts — ingest the 35-belief PrecisionMemBench fixture into an in-memory
 * gbrain (PGLite) the way real content arrives: one page per belief.
 *
 *   - slug === beliefId (so the returned page slug round-trips to the fixture)
 *   - belief.scope[0] → gbrain source_id (registered first; FK requires it)
 *   - body = canonical_name + aliases + content + why_it_matters, so gbrain's
 *     real FTS matches alias queries ("k8s" → kubernetes) — this is gbrain's
 *     keyword search doing real work, not a bench-specific alias index.
 *   - ALL beliefs are seeded LIVE, including superseded ones (audit finding
 *     precisionmembench-01). The upstream provider contract sends providers
 *     only {text, user_id, metadata:{beliefId, scope}, aliases} — never a
 *     supersession field — so leaderboard systems had to infer supersession
 *     from in-band prose ("Previously used TSLint... Replaced by ESLint.").
 *     This harness previously read the fixture's ground-truth `superseded_by`
 *     and pre-hid those beliefs via engine.softDeletePage — the answer key
 *     leaking into the index at seed time. That branch is REMOVED: gbrain
 *     must exclude superseded beliefs itself or fail those cases honestly.
 *     Scores dropped when the leak was removed; the report doc says so.
 *
 * Fidelity (A6):
 *   - 'body-text'  : the above. The everyday ingest path. Ships now.
 *   - 'structured' : exercise gbrain's structured alias/entity layer (facts).
 *                    Deferred to the Phase-4 facts-mode data point — there is
 *                    no page-level alias index beyond FTS, so the honest
 *                    "structured" comparison is the facts path. Throws until
 *                    implemented so we never emit misleading duplicate numbers.
 */

import { PGLiteEngine } from 'gbrain/pglite-engine';
import { importFromContent } from 'gbrain/import-file';
import { loadConfig } from 'gbrain/config';
import { configureGateway } from '../../node_modules/gbrain/src/core/ai/gateway.ts';
import type { BrainEngine } from 'gbrain/engine';
import type { Belief } from './scorer/belief.ts';
import { scopeToSourceId, distinctSourceIds } from './scope.ts';

export type SeedFidelity = 'body-text' | 'structured';

export interface SeedOpts {
  fidelity?: SeedFidelity;
  /** Skip chunk embedding (keyword-only honest fallback when no embed key). */
  noEmbed?: boolean;
}

/** Configure the AI gateway once (mirrors cli.ts#connectEngine + longmemeval). */
export function configureGatewayForBench(overrides: { embeddingModel?: string; embeddingDimensions?: number } = {}): void {
  const cfg = (loadConfig() as unknown as Record<string, unknown>) || {};
  configureGateway({
    embedding_model: overrides.embeddingModel ?? cfg.embedding_model,
    embedding_dimensions: overrides.embeddingDimensions ?? cfg.embedding_dimensions,
    expansion_model: cfg.expansion_model,
    chat_model: cfg.chat_model,
    chat_fallback_chain: cfg.chat_fallback_chain,
    base_urls: cfg.provider_base_urls,
    env: { ...process.env },
  } as Parameters<typeof configureGateway>[0]);
}

/** Fresh in-memory PGLite brain. */
export async function createBenchEngine(searchConfig: Record<string, string> = {}): Promise<PGLiteEngine> {
  const engine = new PGLiteEngine();
  await engine.connect({});
  await engine.initSchema();
  for (const [key, value] of Object.entries(searchConfig)) await engine.setConfig(key, value);
  return engine;
}

/** Register the source rows the beliefs reference (FK target for pages). */
async function registerSources(engine: BrainEngine, beliefs: Belief[]): Promise<void> {
  const ids = distinctSourceIds(beliefs.map((b) => b.scope as string[]));
  for (const sid of ids) {
    if (sid === 'default') continue;
    await engine.executeRaw(
      `INSERT INTO sources (id, name, config) VALUES ($1, $2, '{}'::jsonb)
       ON CONFLICT (id) DO NOTHING`,
      [sid, sid],
    );
  }
}

/** canonical_name + aliases + content + why_it_matters → markdown body. */
function bodyTextFor(b: Belief): string {
  const aliases = (b.aliases ?? []).join(', ');
  const lines = [
    `# ${b.canonical_name}`,
    '',
    aliases ? `Also known as: ${aliases}` : '',
    '',
    b.content ?? '',
    '',
    b.why_it_matters ?? '',
  ];
  return lines.filter((l, i) => !(l === '' && lines[i - 1] === '')).join('\n');
}

/**
 * Ingest beliefs into the engine. Every belief is seeded LIVE — the fixture's
 * ground-truth `superseded_by` is never consulted (see header + audit finding
 * precisionmembench-01). Returns the imported count plus how many superseded
 * beliefs entered the index live, so runners can report the honest setup.
 * Caller separately calls `adapter.loadFixture(beliefs)` to populate seedIndex.
 */
export async function seedGbrainEngine(
  engine: BrainEngine,
  beliefs: Belief[],
  opts: SeedOpts = {},
): Promise<{ imported: number; supersededLive: number }> {
  const fidelity = opts.fidelity ?? 'body-text';
  if (fidelity === 'structured') {
    throw new Error(
      "seed fidelity 'structured' is deferred to the Phase-4 facts-mode data point " +
        '(no page-level alias index beyond FTS). Use --fidelity body-text for now.',
    );
  }

  await registerSources(engine, beliefs);

  let imported = 0;
  let supersededLive = 0;
  for (const b of beliefs) {
    const sourceId = scopeToSourceId((b.scope as string[])[0] ?? 'default');
    await importFromContent(engine, b._id as string, bodyTextFor(b), {
      sourceId,
      noEmbed: opts.noEmbed === true,
    });
    imported++;
    if (b.superseded_by != null) supersededLive++;
  }
  return { imported, supersededLive };
}

